import json,re,hashlib,csv,io,html,collections,urllib.parse,pathlib,datetime
ROOT=pathlib.Path('/mnt/data'); OUT=ROOT/'chrome-bookmark-asset-manager'; OUT.mkdir(exist_ok=True)
source=json.loads((ROOT/'folder-vibe-bookmarks.json').read_text(encoding='utf-8'))
records=[]
def walk(node,path):
 if isinstance(node,list):
  for x in node:walk(x,path)
 elif isinstance(node,dict):
  if node.get('type')=='url':
   u=node.get('url',''); parsed=urllib.parse.urlparse(u);host=(parsed.hostname or '').lower(); segments=[x for x in parsed.path.split('/') if x]
   platform=('github' if host=='github.com' else 'vercel' if host in ('vercel.com','www.vercel.com') else 'ai_studio' if host in ('aistudio.google.com','ai.google.dev') else 'replit' if host in ('replit.com','replit.app') or host.endswith('.replit.app') else 'chatgpt' if host.endswith('chatgpt.com') else 'notion' if host.endswith('notion.site') or host.endswith('notion.so') else 'production' if host.endswith('.vercel.app') else 'website')
   category='reference' if platform in ('chatgpt','notion') else 'candidate'
   slug=''; confidence='unmatched'; kind='other'
   if platform=='github' and len(segments)>=2 and segments[1] not in ('issues','pulls','projects','settings','stars','repositories'):
    slug=segments[1].lower();confidence='high';kind='repository'
   elif platform=='vercel' and len(segments)>=2 and segments[1] not in ('settings','integrations','activity'):
    slug=segments[1].lower();confidence='high';kind='deployment_dashboard'
   elif platform=='production':slug=host.removesuffix('.vercel.app');confidence='medium';kind='production'
   elif platform=='replit':
    if host.endswith('.replit.app'):slug=host.split('.')[0];confidence='medium';kind='production'
    elif segments and segments[0].startswith('@') and len(segments)>1:slug=segments[1].lower();confidence='medium';kind='workspace'
   elif platform=='ai_studio':kind='prototype'
   if not slug and platform=='website' and path and any(x.lower() in ('folder','vibe','my sites','projects','sites','apps') for x in path):
    kind='website';confidence='unmatched'
   canon=urllib.parse.urlunparse((parsed.scheme.lower(),parsed.netloc.lower(),parsed.path.rstrip('/'),'', '', ''))
   records.append({'id':hashlib.sha256((u+'|'+('/'.join(path))).encode()).hexdigest()[:14],'title':node.get('name') or host,'url':u,'canonical_url':canon,'host':host,'platform':platform,'kind':kind,'source_folders':path,'slug':slug,'match_confidence':confidence,'category':category})
  else:
   name=node.get('name','');newpath=path+[name] if name else path
   for ch in node.get('children',[]):walk(ch,newpath)
walk(source.get('profiles',[]),[])
by_slug=collections.defaultdict(list)
for r in records:
 if r['slug'] and r['platform'] in ('github','vercel','production','replit'):by_slug[r['slug']].append(r)
projects=[];used=set()
for slug,items in sorted(by_slug.items()):
 # exact slug match, but do not assume Vercel slug equals repo unless supported by name; mark unverified
 unique=[]
 for r in items:
  if r['id'] not in used:unique.append(r);used.add(r['id'])
 platforms={x['platform'] for x in unique};multi=len(platforms)>1
 links={'github':[],'vercel_dashboard':[],'production':[],'ai_studio':[],'other':[]}
 for r in unique:
  key='github' if r['platform']=='github' else 'vercel_dashboard' if r['platform']=='vercel' else 'production' if r['kind']=='production' else 'other'
  if r['url'] not in links[key]:links[key].append(r['url'])
 projects.append({'id':slug,'name':slug.replace('-',' ').title(),'asset_type':'project_candidate','status':'unverified','links':links,'technology':[],'source_folders':sorted(set(' / '.join(r['source_folders']) for r in unique)),'tags':sorted(platforms),'verification':{'github':'pending','production':'pending','match':'candidate_same_slug' if multi else 'single_platform'},'match_confidence':'medium' if multi else 'high','bookmark_ids':[r['id'] for r in unique]})
# non-identifiable links preserved in unmatched, not coerced into projects
unmatched=[r for r in records if r['id'] not in used]
by_canon=collections.defaultdict(list)
for r in records:by_canon[r['canonical_url']].append(r)
duplicates=[{'canonical_url':u,'bookmark_ids':[r['id'] for r in arr],'occurrences':len(arr)} for u,arr in by_canon.items() if len(arr)>1]
report={'source':'folder-vibe-bookmarks.json','generated_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'bookmark_occurrences':len(records),'candidate_projects':len(projects),'unmatched_links':len(unmatched),'duplicate_url_groups':len(duplicates),'external_checks_performed':False,'note':'Matches based on URL patterns only. Live status, repository-deployment links and technology are unverified.'}
files={'project-registry.json':{'schema_version':1,'projects':projects},'project-links.json':{'schema_version':1,'links':records},'unmatched-links.json':{'schema_version':1,'links':unmatched},'duplicate-candidates.json':{'schema_version':1,'duplicates':duplicates},'link-health-report.json':{'schema_version':1,'status':'not_checked','links_checked':0,'results':[]},'import-review.json':report,'bookmarks-original.json':source}
for filename,data in files.items():(OUT/filename).write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
# Extend existing offline library, retaining its current UI and event handlers.
base=(ROOT/'OPEN-BOOKMARK-LIBRARY-IMPROVED.html').read_text(encoding='utf-8')
style='''<style id="asset-manager-styles">#asset-manager{max-width:1200px;margin:24px auto;padding:22px;background:#151d2b;color:#e9eff9;border:1px solid #39445b;border-radius:16px;font:14px system-ui}#asset-manager *{box-sizing:border-box}#asset-manager h2{font-size:23px;margin:0 0 8px}#asset-manager p{color:#b7c6db}#asset-manager .am-toolbar{display:flex;flex-wrap:wrap;gap:9px;margin:15px 0}#asset-manager input,#asset-manager select{background:#0c1320;border:1px solid #53647d;color:white;border-radius:8px;padding:10px;min-width:140px;flex:1}#asset-manager button{background:#30435f;border:1px solid #64738a;color:white;border-radius:8px;padding:10px 13px;cursor:pointer}#asset-manager button:hover{background:#405d86}#asset-manager .am-metrics{display:flex;flex-wrap:wrap;gap:10px}#asset-manager .am-metrics span{padding:10px;background:#253248;border-radius:8px}#asset-manager .am-list{max-height:620px;overflow:auto;display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:10px}#asset-manager article{background:#1c283a;border:1px solid #394b65;padding:13px;border-radius:10px;overflow-wrap:anywhere}#asset-manager article h3{margin:0 0 6px;font-size:16px}#asset-manager article a{color:#a9caff;display:block;margin:5px 0}#asset-manager small{color:#b4c1d4}#asset-manager .am-note{padding:10px;border-left:3px solid #8fa9d8}#asset-manager .am-actions{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}#asset-manager .am-hidden{display:none}</style>'''
section='''<section id="asset-manager"><h2>Project Asset Manager</h2><p>Offline project discovery from Folder + Vibe bookmarks. Existing bookmark browsing and exports remain available below.</p><div class="am-metrics" id="am-metrics"></div><div class="am-toolbar"><input id="am-search" type="search" placeholder="Search projects, URLs, source folders…"><select id="am-type"><option value="projects">Project candidates</option><option value="all">All bookmark links</option><option value="unmatched">Unmatched links</option><option value="duplicates">Duplicate URL groups</option></select><select id="am-platform"><option value="">All platforms</option><option>github</option><option>vercel</option><option>production</option><option>replit</option><option>ai_studio</option><option>chatgpt</option><option>notion</option><option>website</option></select></div><div class="am-actions"><button id="am-json">Export filtered JSON</button><button id="am-csv">Export filtered CSV</button><button id="am-review">Export review queue</button><button id="am-health">Export health-check queue</button></div><p class="am-note">Matches are URL-derived candidates, not verified deployments. No live checks or authenticated account reads have been performed. Private links must stay local.</p><div id="am-count"></div><div class="am-list" id="am-list"></div></section>'''
script='''<script id="am-data" type="application/json">__DATA__</script><script id="am-code">(function(){'use strict';const d=JSON.parse(document.getElementById('am-data').textContent),q=document.getElementById('am-search'),t=document.getElementById('am-type'),p=document.getElementById('am-platform'),list=document.getElementById('am-list'),count=document.getElementById('am-count');const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function getRows(){let a=t.value==='projects'?d.projects:t.value==='unmatched'?d.unmatched:t.value==='duplicates'?d.duplicates:d.links;let needle=q.value.toLowerCase().trim(),platform=p.value;return a.filter(x=>(!needle||JSON.stringify(x).toLowerCase().includes(needle))&&(!platform||JSON.stringify(x.platform||x.tags||[]).includes(platform)))}function render(){const a=getRows();count.textContent=a.length+' matching records';list.innerHTML=a.slice(0,300).map(x=>{if(x.links){let urls=Object.entries(x.links).flatMap(([k,v])=>v.map(u=>[k,u]));return '<article><h3>'+safe(x.name)+'</h3><small>'+safe(x.id)+' · '+safe(x.verification.match)+' · unverified</small>'+urls.map(([k,u])=>'<a target="_blank" rel="noopener noreferrer" href="'+safe(u)+'">'+safe(k)+': '+safe(u)+'</a>').join('')+'<small>Source: '+safe(x.source_folders.join(' | '))+'</small></article>'}if(x.canonical_url&&!x.url)return '<article><h3>Duplicate ('+x.occurrences+')</h3><small>'+safe(x.canonical_url)+'</small></article>';return '<article><h3>'+safe(x.title)+'</h3><small>'+safe(x.platform)+' · '+safe(x.kind)+'</small><a target="_blank" rel="noopener noreferrer" href="'+safe(x.url)+'">'+safe(x.url)+'</a><small>'+safe(x.source_folders.join(' / '))+'</small></article>'}).join('');if(a.length>300)count.textContent+=' (first 300 displayed; exports include all filtered records)'}function save(filename,data,mime){let blob=new Blob([data],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function csv(rows){let cols=['id','name','title','url','platform','kind','source_folders','match_confidence','status'];return [cols.join(','),...rows.map(x=>cols.map(k=>'"'+String(Array.isArray(x[k])?x[k].join(' | '):x[k]??'').replace(/"/g,'""')+'"').join(','))].join('\\r\\n')}for(let e of [q,t,p])e.addEventListener('input',render);document.getElementById('am-json').onclick=()=>save('filtered-asset-records.json',JSON.stringify(getRows(),null,2),'application/json');document.getElementById('am-csv').onclick=()=>save('filtered-asset-records.csv',csv(getRows()),'text/csv');document.getElementById('am-review').onclick=()=>save('project-match-review.json',JSON.stringify(d.projects.filter(x=>x.verification.match==='candidate_same_slug'),null,2),'application/json');document.getElementById('am-health').onclick=()=>save('link-health-check-queue.json',JSON.stringify({status:'pending',urls:[...new Set(d.links.filter(x=>['production','website'].includes(x.platform)).map(x=>x.url))]},null,2),'application/json');document.getElementById('am-metrics').innerHTML='<span>'+d.report.bookmark_occurrences+' bookmarks</span><span>'+d.report.candidate_projects+' project candidates</span><span>'+d.report.unmatched_links+' unmatched</span><span>'+d.report.duplicate_url_groups+' duplicate groups</span>';render()})();</script>'''
embed={'projects':projects,'links':records,'unmatched':unmatched,'duplicates':duplicates,'report':report}
script=script.replace('__DATA__',json.dumps(embed,ensure_ascii=False,separators=(',',':')).replace('</','<\\/'))
base=base.replace('</head>',style+'</head>',1).replace('<body>','<body>'+section+script,1)
(OUT/'OPEN-BOOKMARK-LIBRARY-ASSET-MANAGER.html').write_text(base,encoding='utf-8')
(OUT/'README.md').write_text('''# Chrome Bookmark Library — Asset Manager\n\nOpen `OPEN-BOOKMARK-LIBRARY-ASSET-MANAGER.html` locally in Chrome. The existing library and bookmark exports remain available. The added manager supports project discovery, searching, filtering, project links, candidate matching, duplicate review, and filtered JSON/CSV exports.\n\n## Generated records\n- `bookmarks-original.json` — preserved input\n- `project-registry.json` — candidate projects; **not verified**\n- `project-links.json` — all source links and classifications\n- `unmatched-links.json` — links not associated with a URL-derived project\n- `duplicate-candidates.json` — canonical URL duplicates\n- `link-health-report.json` — explicitly pending (no external checks run)\n- `import-review.json` — statistics\n\n## Refresh\nRun `python build_asset_manager.py` from a folder containing `folder-vibe-bookmarks.json` and `OPEN-BOOKMARK-LIBRARY-IMPROVED.html`, or use the included original paths as a starting point. The builder is read-only with respect to inputs.\n\n## Limits\nNo GitHub/Vercel API verification, website screenshots, live HTTP health checks, scheduled change detection, or framework detection have been performed. These require online integration. Do not publish this package: it contains personal and dashboard links.\n''',encoding='utf-8')
print(report)
